// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address caller, address recipient, uint256 amount) public {
        vm.assume(caller != address(this));
        vm.assume(recipient != address(c));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        bool ok;
        vm.prank(caller);
        try c.withdrawAll(recipient) { ok = true; } catch { ok = false; }
        uint256 balanceAfter = address(c).balance;
        if (caller == c.owner()) {
            assertTrue(ok && balanceAfter == 0 && address(recipient).balance == balanceAfter + amount);
        } else {
            assertTrue(!ok && balanceAfter == balanceBefore);
        }
    }
}
